import{_ as t,o as e,c as o,a4 as a}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"ZTE UZ901 热点 NVRAM 经验总结","description":"","frontmatter":{"title":"ZTE UZ901 热点 NVRAM 经验总结","date":"2026-07-01T00:00:00.000Z"},"headers":[],"relativePath":"posts/ZTE_UZ901_NVRAM经验总结.md","filePath":"posts/ZTE_UZ901_NVRAM经验总结.md"}'),c={name:"posts/ZTE_UZ901_NVRAM经验总结.md"};function r(l,d,i,n,s,h){return e(),o("div",null,[...d[0]||(d[0]=[a('<h1 id="zte-uz901-热点-nvram-经验总结" tabindex="-1">ZTE UZ901 热点 NVRAM 经验总结 <a class="header-anchor" href="#zte-uz901-热点-nvram-经验总结" aria-label="Permalink to &quot;ZTE UZ901 热点 NVRAM 经验总结&quot;">​</a></h1><h2 id="事故经过" tabindex="-1">事故经过 <a class="header-anchor" href="#事故经过" aria-label="Permalink to &quot;事故经过&quot;">​</a></h2><ol><li>删除了 <code>/mnt/userdata/etc_rw/psnv/rw_backup</code>（160KB，NVRAM 持久化运行数据）</li><li>删除了 <code>/mnt/userdata/etc_rw/nv/backup/</code> 目录（内含 cfg + ro 校准状态文件）</li><li>当时系统正常运行，未发现问题</li><li>重启后 SIM 卡无法识别（&quot;modem_sim_undetected&quot;）</li></ol><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h2><h3 id="nvram-双缓冲机制" tabindex="-1">NVRAM 双缓冲机制 <a class="header-anchor" href="#nvram-双缓冲机制" aria-label="Permalink to &quot;NVRAM 双缓冲机制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>路径</th><th>大小</th><th>作用</th></tr></thead><tbody><tr><td><code>rw_work</code></td><td><code>.../psnv/</code></td><td>160KB</td><td>运行时 NVRAM（modem 当前正在写的）</td></tr><tr><td><code>rw_backup</code></td><td><code>.../psnv/</code></td><td>160KB</td><td>持久备份（用于开机恢复）</td></tr><tr><td><code>work_flag</code></td><td><code>.../psnv/</code></td><td>1B</td><td>工作区标记</td></tr><tr><td><code>backup_flag</code></td><td><code>.../psnv/</code></td><td>1B</td><td>备份区标记</td></tr><tr><td><code>cfg</code></td><td><code>.../nv/main/</code></td><td>17KB</td><td>主要校准配置</td></tr><tr><td><code>cfg</code></td><td><code>.../nv/backup/</code></td><td>17KB</td><td>备份校准配置</td></tr><tr><td><code>ro</code></td><td><code>.../nv/main/</code></td><td>144B</td><td>只读配置</td></tr><tr><td><code>ro</code></td><td><code>.../nv/backup/</code></td><td>144B</td><td>只读配置备份</td></tr></tbody></table><p><code>zte_ufi</code> 守护进程管理这套机制。开机流程：</p><ol><li>读取 <code>psnv/rw_backup</code> → 恢复 modem 状态（卡槽、射频、频段等）</li><li>运行时写入 <code>psnv/rw_work</code></li><li>周期性同步 <code>rw_work</code> → <code>rw_backup</code>（双缓冲，带 flag 标记一致性）</li><li><code>nv/main/cfg</code> 存增量校准，<code>nv/backup/cfg</code> 是对影</li></ol><h3 id="为什么删除后当时没事" tabindex="-1">为什么删除后当时没事 <a class="header-anchor" href="#为什么删除后当时没事" aria-label="Permalink to &quot;为什么删除后当时没事&quot;">​</a></h3><p>删除的是 flash 上的文件。modem 和 <code>zte_ufi</code> 已经把数据加载到了内存中继续运行。系统重建的空文件不会影响运行中的进程。<strong>但重启后，modem 初始化拿到的是一套默认空状态，卡槽/射频参数全错，SIM 检测失败。</strong></p><h3 id="为什么系统自己重建不能用" tabindex="-1">为什么系统自己重建不能用 <a class="header-anchor" href="#为什么系统自己重建不能用" aria-label="Permalink to &quot;为什么系统自己重建不能用&quot;">​</a></h3><p>系统重建的文件 MD5 与备份完全不同（<code>a86e7a92</code> vs <code>a19c65fd</code>），说明重建的内容是出厂初始化写入的默认值，不是运行时积累的有效数据。只有来自运行状态的备份才能正确恢复 modem。</p><h2 id="恢复方法" tabindex="-1">恢复方法 <a class="header-anchor" href="#恢复方法" aria-label="Permalink to &quot;恢复方法&quot;">​</a></h2><ol><li>重启前做了完整 MTD 备份（<code>userdata.bin</code> = mtd5）</li><li>用 <code>jefferson</code> 解压 JFFS2 镜像</li><li><code>adb push</code> 覆盖以下文件： <ul><li><code>psnv/rw_backup</code></li><li><code>psnv/rw_work</code></li><li><code>nv/backup/cfg</code></li><li><code>nv/main/cfg</code></li></ul></li><li>重启后 modem 读取正确 NVRAM，SIM 恢复正常</li></ol><h2 id="教训" tabindex="-1">教训 <a class="header-anchor" href="#教训" aria-label="Permalink to &quot;教训&quot;">​</a></h2><ul><li><strong>NVRAM 文件看起来一样其实不一样</strong>——<code>rw_backup</code> 和 <code>rw_work</code> 即使 MD5 相同，也比空文件重要得多</li><li><strong>删除后当时没事 ≠ 安全</strong>，双缓冲数据依赖状态一致性</li><li><strong>做操作前备份整个 MTD 分区</strong>——这次救命的正是备份</li><li><strong>jffs2 上 rm 是真正的删除，没有回收站</strong>。删除的文件如果被 GC 擦除就永久丢失</li><li><strong>留 236KB 空闲 userdata ≠ 可以随便删</strong>，关键文件删了重启就暴雷</li><li><code>psnv/rw_backup</code> + <code>nv/backup/</code> 是 <strong>禁区</strong>——生产环境绝不应该动</li></ul>',16)])])}const p=t(c,[["render",r]]);export{u as __pageData,p as default};
